class Cuenta
{
    public decimal Saldo { get; private set; }
    public Cuenta(decimal saldo) => Saldo = saldo;
    public void Depositar(decimal monto) { if (monto > 0) Saldo += monto; }
    public void Retirar(decimal monto) { if (monto > 0 && monto <= Saldo) Saldo -= monto; }
    public void TransferirA(Cuenta destino, decimal monto)
    {
        if (Saldo < monto) return;
        Retirar(monto);
        destino.Depositar(monto);
    }
}

